import type { Dispatch, SetStateAction } from 'react';
import type { MetadataRecord, MetadataValue } from '@/lib/digital-twin-projects';

type ComponentInspectorProps = {
  metadata: MetadataRecord | null;
  showGroundPlane: boolean;
  setShowGroundPlane: Dispatch<SetStateAction<boolean>>;
  showKeyLight: boolean;
  setShowKeyLight: Dispatch<SetStateAction<boolean>>;
  onClear: () => void;
};

function formatMetadataValue(value: MetadataValue) {
  if (value === null) {
    return 'null';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

function getTitle(metadata: MetadataRecord | null) {
  if (!metadata) {
    return 'Component metadata';
  }

  const title = metadata.displayName ?? metadata.name ?? metadata.externalId;

  return typeof title === 'string' && title.length > 0
    ? title
    : 'Component metadata';
}

export function ComponentInspector({
  metadata,
  showGroundPlane,
  setShowGroundPlane,
  showKeyLight,
  setShowKeyLight,
  onClear,
}: ComponentInspectorProps) {
  const entries = metadata ? Object.entries(metadata) : [];

  return (
    <aside className="flex min-h-[320px] flex-col gap-4 border-t border-card-border bg-[#0C0C0D]/70 p-4 backdrop-blur-xl lg:min-h-[520px] lg:basis-1/4 lg:border-l lg:border-t-0">
      <div className="rounded-2xl border border-white/15 bg-[#151E2F80] p-4">
        <p className="chakra-petch text-sm font-semibold uppercase tracking-[0.16em] text-gray-300">
          View controls
        </p>
        <div className="mt-4 flex flex-col gap-3 text-sm text-gray-200">
          <label className="flex items-center justify-between gap-3">
            <span>Ground</span>
            <input
              type="checkbox"
              checked={showGroundPlane}
              onChange={(event) => setShowGroundPlane(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
          <label className="flex items-center justify-between gap-3">
            <span>Light</span>
            <input
              type="checkbox"
              checked={showKeyLight}
              onChange={(event) => setShowKeyLight(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
        </div>
      </div>

      <div className="flex min-h-0 flex-1 flex-col rounded-2xl border border-white/15 bg-[#151E2F80] p-4">
        <div className="flex items-start justify-between gap-3">
          <div>
            <p className="chakra-petch text-lg font-semibold text-white">
              {getTitle(metadata)}
            </p>
            <p className="mt-1 text-xs uppercase tracking-[0.16em] text-gray-500">
              Inspection
            </p>
          </div>
          {metadata ? (
            <button
              type="button"
              onClick={onClear}
              className="rounded-full border border-white/15 px-3 py-1 text-xs text-gray-300 transition hover:border-primary/50 hover:text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
            >
              Clear
            </button>
          ) : null}
        </div>

        {entries.length > 0 ? (
          <dl className="mt-4 flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto pr-1">
            {entries.map(([key, value]) => (
              <div key={key} className="rounded-xl bg-[#0C0C0D]/55 p-3">
                <dt className="text-xs uppercase tracking-[0.14em] text-gray-500">
                  {key}
                </dt>
                <dd className="mt-1 break-words font-mono text-xs leading-relaxed text-gray-200">
                  {formatMetadataValue(value)}
                </dd>
              </div>
            ))}
          </dl>
        ) : (
          <div className="mt-4 flex flex-1 items-center rounded-xl border border-dashed border-white/15 p-4 text-sm leading-6 text-gray-400">
            Click a component to inspect its metadata. Any available name-value
            pairs from the loaded model will appear here.
          </div>
        )}
      </div>
    </aside>
  );
}

