'use client';

// cspell:words drei GLTF gltf
import {
  Bounds,
  Environment,
  Html,
  OrbitControls,
  useBounds,
  useGLTF,
} from '@react-three/drei';
import { Canvas, type ThreeEvent } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Box3, Vector3, type Mesh, type Object3D } from 'three';
import { ComponentInspector } from '@/components/digital-twin/component-inspector';
import type {
  ConstructionMilestone,
  DigitalTwinComponentConfig,
  MetadataRecord,
  MetadataValue,
} from '@/lib/digital-twin-projects';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  statusLabel: string;
  milestones?: ConstructionMilestone[];
  components?: DigitalTwinComponentConfig[];
};

type GltfCatalogElement = MetadataRecord & {
  externalId?: MetadataValue;
  id?: MetadataValue;
  name?: MetadataValue;
  modelNodeName?: MetadataValue;
};

function isMesh(object: Object3D): object is Mesh {
  return 'isMesh' in object && object.isMesh === true;
}

function buildEnabledNameSet(milestones: ConstructionMilestone[]) {
  const names = new Set<string>();

  milestones.forEach((milestone) => {
    if (!milestone.completed) {
      return;
    }

    milestone.components.forEach((component) => {
      component.nodeNames.forEach((nodeName) => names.add(nodeName));
    });
  });

  return names;
}

function hasEnabledName(object: Object3D, enabledNames: Set<string>) {
  let current: Object3D | null = object;

  while (current) {
    if (enabledNames.has(current.name)) {
      return true;
    }

    current = current.parent;
  }

  return false;
}

function isMetadataRecord(value: unknown): value is MetadataRecord {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function asMetadataValue(value: unknown): MetadataValue | undefined {
  if (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return value;
  }

  if (Array.isArray(value)) {
    const values = value
      .map(asMetadataValue)
      .filter((item): item is MetadataValue => item !== undefined);

    return values;
  }

  if (isMetadataRecord(value)) {
    return Object.fromEntries(
      Object.entries(value)
        .map(([key, item]) => [key, asMetadataValue(item)] as const)
        .filter(
          (entry): entry is readonly [string, MetadataValue] =>
            entry[1] !== undefined
        )
    );
  }

  return undefined;
}

function normalizeRecord(record: Record<string, unknown>) {
  return Object.fromEntries(
    Object.entries(record)
      .map(([key, value]) => [key, asMetadataValue(value)] as const)
      .filter(
        (entry): entry is readonly [string, MetadataValue] =>
          entry[1] !== undefined
      )
  );
}

function getStringValue(record: MetadataRecord, keys: string[]) {
  for (const key of keys) {
    const value = record[key];

    if (typeof value === 'string' && value.length > 0) {
      return value;
    }
  }

  return undefined;
}

function buildComponentRecord(component: DigitalTwinComponentConfig) {
  return normalizeRecord({
    externalId: component.externalId,
    displayName: component.displayName,
    nodeNames: component.nodeNames,
    defaultVisible: component.defaultVisible,
  });
}

function findCatalogMatch(
  catalog: GltfCatalogElement[],
  identityValues: Set<string>
) {
  return catalog.find((element) => {
    const candidates = [
      element.externalId,
      element.id,
      element.name,
      element.modelNodeName,
    ];

    return candidates.some(
      (candidate) =>
        typeof candidate === 'string' && identityValues.has(candidate)
    );
  });
}

function collectMetadata(
  object: Object3D,
  components: DigitalTwinComponentConfig[],
  catalog: GltfCatalogElement[]
) {
  const metadata: MetadataRecord = {};
  const identityValues = new Set<string>();
  let current: Object3D | null = object;
  let depth = 0;

  while (current) {
    if (current.name) {
      const key = depth === 0 ? 'name' : `parent_${depth}_name`;
      metadata[key] = current.name;
      identityValues.add(current.name);
    }

    metadata[depth === 0 ? 'type' : `parent_${depth}_type`] = current.type;

    const userData = normalizeRecord(current.userData);
    Object.assign(metadata, userData);

    const externalId = getStringValue(userData, [
      'externalId',
      'id',
      'name',
      'displayName',
      'modelNodeName',
    ]);

    if (externalId) {
      identityValues.add(externalId);
    }

    current = current.parent;
    depth += 1;
  }

  const component = components.find(
    (item) =>
      identityValues.has(item.externalId) ||
      identityValues.has(item.displayName) ||
      item.nodeNames.some((nodeName) => identityValues.has(nodeName))
  );

  if (component) {
    Object.assign(metadata, buildComponentRecord(component));
    identityValues.add(component.externalId);
    component.nodeNames.forEach((nodeName) => identityValues.add(nodeName));
  }

  const catalogMatch = findCatalogMatch(catalog, identityValues);

  if (catalogMatch) {
    Object.assign(metadata, catalogMatch);
  }

  return metadata;
}

function Model({
  modelUrl,
  statusLabel,
  milestones = [],
  components = [],
  onSelectMetadata,
}: {
  modelUrl: string;
  statusLabel: string;
  milestones?: ConstructionMilestone[];
  components?: DigitalTwinComponentConfig[];
  onSelectMetadata: (metadata: MetadataRecord) => void;
}) {
  const gltf = useGLTF(modelUrl);
  const bounds = useBounds();
  const isOperational = statusLabel === 'Operational';
  const enabledNames = useMemo(
    () => buildEnabledNameSet(milestones),
    [milestones]
  );
  const modelOffset = useMemo(() => {
    const box = new Box3().setFromObject(gltf.scene);
    const center = box.getCenter(new Vector3());

    return new Vector3(-center.x, -box.min.y, -center.z);
  }, [gltf.scene]);
  const catalog = useMemo(() => {
    const elements = gltf.parser.json.extras?.elements;

    return Array.isArray(elements)
      ? elements
          .filter(isMetadataRecord)
          .map((element) => normalizeRecord(element) as GltfCatalogElement)
      : [];
  }, [gltf.parser.json.extras?.elements]);

  useEffect(() => {
    gltf.scene.traverse((object) => {
      if (!isMesh(object)) {
        object.visible = true;
        return;
      }

      object.visible = isOperational || hasEnabledName(object, enabledNames);
      object.castShadow = object.visible;
      object.receiveShadow = object.visible;
    });

    bounds.refresh(gltf.scene).fit();
  }, [bounds, enabledNames, gltf.scene, isOperational]);

  const handleClick = (event: ThreeEvent<MouseEvent>) => {
    event.stopPropagation();
    onSelectMetadata(collectMetadata(event.object, components, catalog));
  };

  const handlePointerOver = (event: ThreeEvent<PointerEvent>) => {
    event.stopPropagation();
    document.body.style.cursor = 'pointer';
  };

  const handlePointerOut = () => {
    document.body.style.cursor = 'default';
  };

  return (
    <primitive
      object={gltf.scene}
      position={modelOffset}
      onClick={handleClick}
      onPointerOver={handlePointerOver}
      onPointerOut={handlePointerOut}
    />
  );
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

export function DigitalTwinModelViewer({
  modelUrl,
  statusLabel,
  milestones,
  components,
}: DigitalTwinModelViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [showGroundPlane, setShowGroundPlane] = useState(true);
  const [showKeyLight, setShowKeyLight] = useState(true);
  const [selectedMetadata, setSelectedMetadata] =
    useState<MetadataRecord | null>(null);
  const [inspectorWidth, setInspectorWidth] = useState(25);

  const handleResizeStart = () => {
    const handleResize = (event: PointerEvent) => {
      const container = containerRef.current;

      if (!container) {
        return;
      }

      const rect = container.getBoundingClientRect();
      const nextWidth = ((rect.right - event.clientX) / rect.width) * 100;

      setInspectorWidth(Math.min(45, Math.max(18, nextWidth)));
    };

    const handleResizeEnd = () => {
      document.body.style.cursor = 'default';
      window.removeEventListener('pointermove', handleResize);
      window.removeEventListener('pointerup', handleResizeEnd);
    };

    document.body.style.cursor = 'col-resize';
    window.addEventListener('pointermove', handleResize);
    window.addEventListener('pointerup', handleResizeEnd);
  };

  return (
    <section className="overflow-hidden rounded-[28px] border border-card-border bg-card-bg shadow-2xl backdrop-blur-xl">
      <div ref={containerRef} className="flex flex-col lg:flex-row">
        <div
          className={`relative h-[520px] ${showGroundPlane ? 'bg-[#6f6f6f]' : 'bg-[#808080]'}`}
          style={{ flexBasis: `calc(100% - ${inspectorWidth}%)` }}
        >
          <Canvas
            camera={{ position: [5, 4, 8], fov: 45 }}
            shadows
            gl={{ antialias: true }}
          >
            <color
              attach="background"
              args={[showGroundPlane ? '#6f6f6f' : '#808080']}
            />
            <ambientLight intensity={0.55} />
            <hemisphereLight args={['#f7f7f7', '#2c2c2c', 0.85]} />
            {showKeyLight ? (
              <directionalLight
                position={[45, 90, 45]}
                intensity={4.8}
                castShadow
                shadow-mapSize={[4096, 4096]}
                shadow-camera-near={1}
                shadow-camera-far={180}
                shadow-camera-left={-90}
                shadow-camera-right={90}
                shadow-camera-top={90}
                shadow-camera-bottom={-90}
                shadow-bias={-0.0002}
                shadow-normalBias={0.08}
              />
            ) : null}
            <Environment preset="city" environmentIntensity={0.35} />
            <Suspense fallback={<LoadingModel />}>
              <Bounds clip margin={1.35}>
                <group>
                  {showGroundPlane ? (
                    <group position={[0, 0, 0]}>
                      <gridHelper args={[76, 38, '#d8d8d8', '#a8a8a8']} />
                      <mesh
                        rotation={[-Math.PI / 2, 0, 0]}
                        position={[0, -0.01, 0]}
                        receiveShadow
                      >
                        <planeGeometry args={[76, 76]} />
                        <meshStandardMaterial
                          color="#505050"
                          roughness={0.95}
                        />
                      </mesh>
                    </group>
                  ) : null}
                  <Model
                    modelUrl={modelUrl}
                    statusLabel={statusLabel}
                    milestones={milestones}
                    components={components}
                    onSelectMetadata={setSelectedMetadata}
                  />
                </group>
              </Bounds>
            </Suspense>
            <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
          </Canvas>
        </div>

        <button
          type="button"
          aria-label="Resize metadata panel"
          onPointerDown={handleResizeStart}
          className="hidden w-2 cursor-col-resize border-l border-r border-white/10 bg-[#0C0C0D]/60 transition hover:bg-primary/20 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary lg:block"
        />

        <ComponentInspector
          metadata={selectedMetadata}
          showGroundPlane={showGroundPlane}
          setShowGroundPlane={setShowGroundPlane}
          showKeyLight={showKeyLight}
          setShowKeyLight={setShowKeyLight}
          style={{ flexBasis: `${inspectorWidth}%` }}
        />
      </div>
    </section>
  );
}

import type { CSSProperties, Dispatch, SetStateAction } from 'react';
import type {
  MetadataRecord,
  MetadataValue,
} from '@/lib/digital-twin-projects';

type ComponentInspectorProps = {
  metadata: MetadataRecord | null;
  showGroundPlane: boolean;
  setShowGroundPlane: Dispatch<SetStateAction<boolean>>;
  showKeyLight: boolean;
  setShowKeyLight: Dispatch<SetStateAction<boolean>>;
  style?: CSSProperties;
};

function formatMetadataValue(value: MetadataValue) {
  if (value === null) {
    return 'null';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

function getTitle(metadata: MetadataRecord | null) {
  if (!metadata) {
    return 'Component metadata';
  }

  const title = metadata.displayName ?? metadata.name ?? metadata.externalId;

  return typeof title === 'string' && title.length > 0
    ? title
    : 'Component metadata';
}

export function ComponentInspector({
  metadata,
  showGroundPlane,
  setShowGroundPlane,
  showKeyLight,
  setShowKeyLight,
  style,
}: ComponentInspectorProps) {
  const entries = metadata ? Object.entries(metadata) : [];

  return (
    <aside
      className="flex max-h-[520px] min-h-[260px] flex-col gap-3 border-t border-card-border bg-[#0C0C0D]/70 p-3 backdrop-blur-xl lg:min-h-[520px] lg:border-l lg:border-t-0"
      style={style}
    >
      <div className="rounded-2xl border border-white/15 bg-[#151E2F80] p-3">
        <p className="chakra-petch text-xs font-semibold uppercase tracking-[0.16em] text-gray-300">
          View controls
        </p>
        <div className="mt-3 flex flex-col gap-2 text-sm text-gray-200">
          <label className="flex items-center justify-between gap-3">
            <span>Ground</span>
            <input
              type="checkbox"
              checked={showGroundPlane}
              onChange={(event) => setShowGroundPlane(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
          <label className="flex items-center justify-between gap-3">
            <span>Light</span>
            <input
              type="checkbox"
              checked={showKeyLight}
              onChange={(event) => setShowKeyLight(event.target.checked)}
              className="h-4 w-4 accent-primary"
            />
          </label>
        </div>
      </div>

      <div className="flex min-h-0 flex-1 flex-col rounded-2xl border border-white/15 bg-[#151E2F80] p-3">
        <p className="chakra-petch text-base font-semibold text-white">
          {getTitle(metadata)}
        </p>

        {entries.length > 0 ? (
          <dl className="mt-3 flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto pr-1">
            {entries.map(([key, value]) => (
              <div
                key={key}
                className="grid grid-cols-[minmax(88px,38%)_1fr] gap-2 rounded-lg bg-[#0C0C0D]/55 px-2 py-1.5"
              >
                <dt className="truncate text-[11px] uppercase tracking-[0.08em] text-gray-500">
                  {key}
                </dt>
                <dd
                  className="truncate font-mono text-[11px] leading-5 text-gray-200"
                  title={formatMetadataValue(value)}
                >
                  {formatMetadataValue(value)}
                </dd>
              </div>
            ))}
          </dl>
        ) : (
          <div className="mt-3 flex flex-1 items-center rounded-xl border border-dashed border-white/15 p-3 text-sm leading-6 text-gray-400">
            Click a component to inspect its metadata. Any available name-value
            pairs from the loaded model will appear here.
          </div>
        )}
      </div>
    </aside>
  );
}

