import type { Dispatch, SetStateAction } from 'react';
import type {
  MetadataRecord,
  MetadataValue,
} from '@/lib/digital-twin-projects';

type ComponentInspectorProps = {
  metadata: MetadataRecord | null;
  showGroundPlane: boolean;
  setShowGroundPlane: Dispatch<SetStateAction<boolean>>;
  showKeyLight: boolean;
  setShowKeyLight: Dispatch<SetStateAction<boolean>>;
};

function formatMetadataValue(value: MetadataValue) {
  if (value === null) {
    return 'null';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

function getTitle(metadata: MetadataRecord | null) {
  if (!metadata) {
    return 'Component metadata';
  }

  const title = metadata.displayName ?? metadata.name ?? metadata.externalId;

  return typeof title === 'string' && title.length > 0
    ? title
    : 'Component metadata';
}

export function ComponentInspector({
  metadata,
  showGroundPlane,
  setShowGroundPlane,
  showKeyLight,
  setShowKeyLight,
}: ComponentInspectorProps) {
  const entries = metadata ? Object.entries(metadata) : [];

  return (
    <aside className="flex max-h-[520px] min-h-[260px] flex-col gap-3 border-t border-card-border bg-[#0C0C0D]/70 p-3 backdrop-blur-xl lg:min-h-[520px] lg:border-l lg:border-t-0">
